deeksha: TS sketch (for docs):

```ts
// read-as-lines + optional resume
async function* streamLines(url: string, cursor?: string) {
  const u = new URL(url);
  if (cursor) u.searchParams.set('cursor', cursor);
  const res = await fetch(u.toString());
  if (!res.body) return;
  const reader = res.body.getReader();
  const dec = new TextDecoder();
  let buf = '';
  while (true) {
    const {done, value} = await reader.read();
    if (done) break;
    buf += dec.decode(value, {stream: true});
    let nl;
    while ((nl = buf.indexOf('\n')) >= 0) {
      yield buf.slice(0, nl);
      buf = buf.slice(nl + 1);
    }
  }
  if (buf) yield buf;
}
```

deeksha: I'll add a tiny wrapper retryFetch that re-calls streamLines using the Resume-Token header when server returns 409.

ton y: Go example (concise):

```go
// simple streaming reader with resume
resp, err := http.Get(url)
if err != nil { return err }
scanner := bufio.NewScanner(resp.Body)
for scanner.Scan() {
  line := scanner.Text()
  if strings.HasPrefix(line, "CURSOR:") {
    cursor = strings.SplitN(line, ":", 2)[1]
  } else {
    fmt.Println(line)
  }
}
```

